mapper.select:
SELECT id, title, category, priority, due_date, completed, completed_at, pinned
FROM todos

    AND deleted_at IS NULL

        AND title LIKE CONCAT('%', #{keyword}, '%')


        AND category = #{category}


        AND completed = FALSE


        AND due_date >= #{from}


        AND due_date <= #{to}



    ORDER BY pinned DESC, due_date DESC
    ORDER BY pinned DESC, due_date ASC
